 spec=dict(task_id=ident,task_contract_sha256=mc.digest_object(task),target=task['name'],model=texts[ident],observation_law='Explicit in derivation and fixed scenario cells',sampling_unit='Stationary synthetic calendar under the declared law',method=module,assumptions=['Correct supplied information class','Recorded dependence and moment/rank conditions','Fresh independent Monte Carlo requests'],uncertainty_claim='Scoped argument and finite grid screen, not general finite or bank qualification',alternatives=methods[1:],adverse_cases=[d['name'] for d in designs if d.get('adverse')],metrics=['all-request coverage','class retention where applicable','set topology','width','bias','SE/SD','time','process peak RSS'],acceptance_rules=dict(minimum_coverage=.95,minimum_finite_fraction=.99,simultaneous_error=.05,family=16,bank_width_threshold=None),replications=512,seed=202610114403 if ident=='R04' else 202610115502,stopping_rule='fixed_design_no_outcome_stopping',derivation_review=dict(path=str(review),sha256=mc.sha(review),anchor='Full scoped argument and independent pre-evaluation checks'),input_sha256={f:mc.sha(Path(f)) for f in files},module=module,alpha=.01,designs=designs,methods=methods,**extra)
 spec['monte_carlo_design']=dict(planned_coverage=.95,anticipated_interval=exact_interval(round(.95*512),512,.05/16),tolerated_error=.04)
